#include <stdio.h>

/* 空闲分区链（按地址递增），要分配 212K */
int free_blk[5] = {100, 500, 200, 300, 600};
#define N 5

int first_fit(int need) {
    for (int i = 0; i < N; i++) if (free_blk[i] >= need) return i;
    return -1;
}
int best_fit(int need) {
    int best = -1;
    for (int i = 0; i < N; i++)
        if (free_blk[i] >= need && (best == -1 || free_blk[i] < free_blk[best])) best = i;
    return best;
}
int worst_fit(int need) {
    int w = -1;
    for (int i = 0; i < N; i++)
        if (free_blk[i] >= need && (w == -1 || free_blk[i] > free_blk[w])) w = i;
    return w;
}

int main(void) {
    int need = 212;
    int a = first_fit(need), b = best_fit(need), c = worst_fit(need);
    printf("free blocks (address ascending): ");
    for (int i = 0; i < N; i++) printf("%d%s", free_blk[i], i + 1 < N ? ", " : "\n");
    printf("request = %d K\n", need);
    printf("first-fit : pick size=%d  leftover=%d K\n", free_blk[a], free_blk[a] - need);
    printf("best-fit  : pick size=%d  leftover=%d K  <- smallest hole\n", free_blk[b], free_blk[b] - need);
    printf("worst-fit : pick size=%d  leftover=%d K  <- largest hole\n", free_blk[c], free_blk[c] - need);
    printf("best-fit keeps the smallest hole: many tiny unusable fragments\n");
    printf("best-fit is theoretically tight but practically worst\n");
    return 0;
}
